import pytest
from datetime import date
from latefee import LateFeeCalculator  # adjust import

MON = date(2024, 1, 1)  # Monday

def calc(today): return LateFeeCalculator(today)

def test_default_today_no_arg():
    assert LateFeeCalculator().compute_fee_cents(0, MON) == 0

@pytest.mark.parametrize("bal", [0, -100])
def test_nonpositive_balance(bal):
    assert calc(date(2025, 1, 1)).compute_fee_cents(bal, MON) == 0

def test_end_before_start():
    assert calc(date(2023, 1, 1)).compute_fee_cents(100000, MON) == 0

def test_end_equals_start():
    assert calc(MON).compute_fee_cents(100000, MON) == 0

def test_within_grace_exact_10_weekdays():
    # 14 cal days = 10 weekdays
    assert calc(MON + __import__("datetime").timedelta(days=14)).compute_fee_cents(100000, MON) == 0

def test_weekend_skipped():
    c = calc(date(2024, 1, 8))  # 5 weekdays
    assert c.compute_fee_cents(100000, MON) == 0

def test_min_fee_floor():
    # 11 weekdays -> 1 billable day -> tiny raw fee
    assert calc(date(2024, 1, 16)).compute_fee_cents(100000, MON) == 500

def test_normal_fee_between_bounds():
    # large balance, 1 billable day: 10_000_000 * .0005 = 5000
    assert calc(date(2024, 1, 16)).compute_fee_cents(10_000_000, MON) == 5000

def test_max_cap():
    assert calc(date(2026, 1, 1)).compute_fee_cents(10_000_000, MON) == 2_500_000

def test_round_half_up():
    # raw = 1000*.0005*1 = 0.5 -> 1, but min fee applies
    assert calc(date(2024, 1, 16)).compute_fee_cents(1000, MON) == 500
